# Generated by extendr: Do not edit by hand
args <- commandArgs(trailingOnly = TRUE)
r_pkg_name <- args[[1]]
shlib <- args[[2]]
path_to_wrappers <- args[[3]]

dll <- dyn.load(shlib)

wrappers <- .Call(
  "wrap__make_{{{mod_name}}}_wrappers",
  TRUE,
  r_pkg_name,
  PACKAGE = dll[["name"]]
)

# strip last blank line
wrappers <- sub("\\s+$", "", wrappers)

writeLines(
  c(
    "# Generated by extendr: Do not edit by hand",
    "# nolint start",
    "",
    "#' @usage NULL",
    sprintf("#' @useDynLib %s, .registration = TRUE", r_pkg_name),
    "NULL",
    "",
    wrappers,
    "",
    "# nolint end"
  ),
  path_to_wrappers
)